-- 0012_release_ecoline_unnion.sql
-- Libera para producao as 12 formulas Ecoline 2.5 (id 3-8) e UNNION (id 23-28),
-- selecionadas explicitamente pelo responsavel tecnico ("libera tudo do Ecoline
-- e UNNION") apos revisar a lista completa das 48 formulas elegiveis (linhas
-- ja totalmente catalogadas). As outras 36 formulas elegiveis (Gold III,
-- Suprema) continuam CATALOGADO/bloqueadas ate uma decisao equivalente.
--
-- Marca as formula_deductions dessas 12 versoes como VALIDADO (constante
-- confirmada, nao so extraida) e registra formula_validations, prototypes e
-- technical_approvals com nota explicita sobre a base da aprovacao: uso
-- comprovado em producao real, nao um novo prototipo fisico desta sessao.
-- Ver docs/GOVERNANCA_DE_DADOS.md.

UPDATE formula_deductions SET status_code='VALIDADO' WHERE formula_version_id IN (3,4,5,6,7,8,23,24,25,26,27,28);

UPDATE formula_versions SET status_code='LIBERADO_PRODUCAO', production_locked=0 WHERE id=3;
UPDATE formulas SET status_code='LIBERADO_PRODUCAO' WHERE id=3;

